using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
public class SetupWizard:Window {
 readonly bool uninstall;readonly InstallOptions options;readonly StackPanel content;readonly TextBlock step,error;readonly Button back,next,cancel;TextBox targetBox,log;CheckBox desktop,startMenu,launch;ProgressBar progress;int page;bool working;volatile bool committing;CancellationTokenSource cancellation;InstallState installed;public int ResultCode{get;private set;}
 public SetupWizard(string target,bool removing){uninstall=removing;options=new InstallOptions{Target=target,Previous=removing?"":Setup.RegisteredPath()};Title="瞎折腾 TV 助手 · "+(removing?"卸载":"安装")+"向导";Width=860;Height=710;MinWidth=760;MinHeight=620;WindowStartupLocation=WindowStartupLocation.CenterScreen;FontFamily=new FontFamily("Microsoft YaHei UI");FontSize=13;Foreground=Brush("#332A40");Background=new LinearGradientBrush(Color.FromRgb(240,246,255),Color.FromRgb(255,243,249),30);ResultCode=1;
 var assembly=Assembly.GetExecutingAssembly();using(var icon=assembly.GetManifestResourceStream("logo.ico"))Icon=BitmapFrame.Create(icon,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);using(var theme=assembly.GetManifestResourceStream("theme.xaml"))Resources.MergedDictionaries.Add((ResourceDictionary)System.Windows.Markup.XamlReader.Load(theme));
 var root=new DockPanel{Margin=new Thickness(26)};var header=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,2,0,16)};header.Children.Add(new Image{Source=Icon,Width=54,Height=54,Margin=new Thickness(0,0,16,0)});var labels=new StackPanel();labels.Children.Add(Label("瞎折腾 TV 助手",25));labels.Children.Add(Label("还一个干净的TV世界。",12,"#806B91"));header.Children.Add(labels);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);step=Label("",12,"#88729B");step.Margin=new Thickness(0,0,0,18);DockPanel.SetDock(step,Dock.Top);root.Children.Add(step);
 var footer=new DockPanel{Margin=new Thickness(0,18,0,0)};error=Label("",12,"#B04752");error.MaxWidth=460;DockPanel.SetDock(error,Dock.Left);footer.Children.Add(error);var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};back=MakeButton("上一步",()=>Back());next=MakeButton("下一步",()=>Next());next.Tag="Primary";cancel=MakeButton("取消",()=>Cancel());buttons.Children.Add(back);buttons.Children.Add(next);buttons.Children.Add(cancel);footer.Children.Add(buttons);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);content=new StackPanel();root.Children.Add(new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});MacFrame.Attach(this,root);Closing+=(s,e)=>{if(working){e.Cancel=true;if(!committing&&cancellation!=null){cancellation.Cancel();error.Text="正在取消，等待当前文件处理结束…";}else error.Text="正在完成写入，请稍候。";}};ShowPage(0);
