 static Brush Brush(string color){return (Brush)new BrushConverter().ConvertFrom(color);}
 TextBlock Label(string text,int size=14,string color="#332A40"){return new TextBlock{Text=text,FontSize=size,Foreground=Brush(color),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,5)};}
 Button MakeButton(string text,Action action){var button=new Button{Content=text,Padding=new Thickness(18,10,18,10),Margin=new Thickness(5,0,0,0),Background=Brushes.White,BorderBrush=Brush("#E1DCE9")};button.Click+=(s,e)=>{try{action();}catch(Exception ex){error.Text=ex.Message;}};return button;}
 void Heading(string title,string details){content.Children.Add(Label(title,23));content.Children.Add(Label(details,13,"#756481"));}
 void ShowPage(int value){page=value;content.Children.Clear();error.Text="";step.Text=new[]{"01 欢迎","02 安装位置","03 确认选项","04 安装进度","05 完成"}.Select((name,i)=>i==page?"● "+name:name).Aggregate((a,b)=>a+"    "+b);if(uninstall)step.Text=page==4?"卸载完成":"卸载向导 · "+(page+1)+" / 5";back.IsEnabled=page>0&&page<3;next.IsEnabled=page!=3;next.Content=page==2?(uninstall?"确认卸载":"开始安装"):page==4?"完成":"下一步";cancel.IsEnabled=page!=3||!committing;cancel.Visibility=page==4?Visibility.Collapsed:Visibility.Visible;
 if(page==0){Heading(uninstall?"准备卸载 TV 助手":"欢迎安装 TV 助手 "+Setup.Version,uninstall?"只移除安装清单中的程序文件，保留扫描结果、设置和 APK 备份。":"支持自定义安装目录和覆盖升级。请先完成当前电视任务，再继续安装。");content.Children.Add(Label(uninstall?"卸载位置："+options.Target:"接下来将依次选择安装目录、确认快捷方式与安装选项，然后显示真实安装进度。",15));content.Children.Add(Label("用户数据目录：\n"+Setup.DataPath,12));content.Children.Add(Label("安装包自带 ADB、投屏组件、桌面与常用软件，不需要在安装时另行下载这些组件。",13));return;}
 if(page==1){Heading(uninstall?"确认卸载位置":"选择安装位置",uninstall?"安装位置来自当前卸载器，不会按固定默认路径清理其他目录。":"可以填写完整路径，也可以浏览选择独立的软件文件夹。");var row=new DockPanel{Margin=new Thickness(0,18,0,12)};var browse=MakeButton("浏览…",()=>Browse());browse.IsEnabled=!uninstall;DockPanel.SetDock(browse,Dock.Right);row.Children.Add(browse);targetBox=new TextBox{Text=options.Target,Padding=new Thickness(12),IsReadOnly=uninstall};row.Children.Add(targetBox);content.Children.Add(row);content.Children.Add(Label("用户数据仍保存在独立目录，改变安装位置不会迁移或覆盖这些数据。",13));if(!string.IsNullOrWhiteSpace(options.Previous))content.Children.Add(Label("检测到此前安装位置：\n"+options.Previous,12));if(!uninstall){desktop=new CheckBox{Content="创建桌面快捷方式",IsChecked=options.Desktop,Margin=new Thickness(0,18,0,10)};startMenu=new CheckBox{Content="创建开始菜单快捷方式",IsChecked=options.StartMenu,Margin=new Thickness(0,0,0,10)};content.Children.Add(desktop);content.Children.Add(startMenu);}return;}
 if(page==2){Heading(uninstall?"确认卸载":"确认安装选项",uninstall?"确认后移除本目录下的程序文件，其他额外文件和用户数据保留。":"确认下面的信息后开始安装；可以点上一步修改路径。");content.Children.Add(Label((uninstall?"卸载":"安装")+"目录：\n"+options.Target,15));content.Children.Add(Label("用户数据：\n"+Setup.DataPath,12));if(!uninstall){content.Children.Add(Label(Setup.IsInstalled(options.Target)?"安装方式：覆盖升级，旧程序保留为备份。":"安装方式：全新安装。",14));content.Children.Add(Label("桌面快捷方式："+(options.Desktop?"创建":"不创建")+"\n开始菜单快捷方式："+(options.StartMenu?"创建":"不创建"),13));if(!string.IsNullOrWhiteSpace(options.Previous)&&!Setup.Same(options.Previous,options.Target))content.Children.Add(Label("更换安装位置时，旧程序目录保留；新的快捷方式和系统卸载入口指向新目录。",13));}return;}
 if(page==3){Heading(uninstall?"正在卸载":"正在安装","当前阶段会显示在下面，安装完成后仍需点击“完成”。");progress=new ProgressBar{Minimum=0,Maximum=100,Height=15,Margin=new Thickness(0,18,0,18),Foreground=Brush("#9B73E9")};content.Children.Add(progress);log=new TextBox{Height=215,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Padding=new Thickness(12),Background=Brushes.White};content.Children.Add(log);return;}
 if(page==4){Heading(uninstall?"卸载完成":"安装完成",uninstall?"用户数据、旧版备份及额外文件已保留。":"程序已准备就绪，可以点击“完成”启动。");content.Children.Add(Label((uninstall?"原程序目录：":"安装目录：")+options.Target,14));if(installed!=null&&!string.IsNullOrEmpty(installed.Backup))content.Children.Add(Label("旧版备份：\n"+installed.Backup,12));if(!uninstall){launch=new CheckBox{Content="完成后启动 TV 助手",IsChecked=true,Margin=new Thickness(0,22,0,10)};content.Children.Add(launch);content.Children.Add(MakeButton("打开安装目录",()=>Process.Start(new ProcessStartInfo("explorer.exe","\""+options.Target+"\""){UseShellExecute=false})));}content.Children.Add(Label("用户数据目录：\n"+Setup.DataPath,12));}
 }
 void Browse(){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description="选择独立的软件安装文件夹",SelectedPath=targetBox.Text,ShowNewFolderButton=true})if(dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK)targetBox.Text=dialog.SelectedPath;}
 void Back(){if(working)return;if(page==2)ShowPage(1);else if(page==1){RememberPath();ShowPage(0);}}
 void RememberPath(){if(targetBox!=null)options.Target=targetBox.Text.Trim();if(desktop!=null)options.Desktop=desktop.IsChecked==true;if(startMenu!=null)options.StartMenu=startMenu.IsChecked==true;}
 async void Next(){try{if(page==0){ShowPage(1);return;}if(page==1){RememberPath();options.Target=Setup.ValidateTarget(options.Target,uninstall?"":options.Previous);ShowPage(2);return;}if(page==2){await StartJob();return;}if(page==4){if(!uninstall&&launch!=null&&launch.IsChecked==true)Process.Start(new ProcessStartInfo(Path.Combine(options.Target,"TVStudio.exe")){UseShellExecute=true,WorkingDirectory=options.Target});Close();}}catch(Exception ex){error.Text=ex.Message;}}
 async Task StartJob(){working=true;committing=uninstall;cancellation=new CancellationTokenSource();ShowPage(3);await Task.Yield();Action<InstallProgress> report=p=>{if(p.Committing)committing=true;Dispatcher.BeginInvoke(new Action(()=>{if(page!=3)return;progress.Value=p.Percent;log.AppendText(p.Percent+"%  "+p.Message+Environment.NewLine);log.ScrollToEnd();cancel.IsEnabled=!committing;}));};try{await Task.Run(()=>{if(uninstall)Setup.Uninstall(options.Target,true,report);else installed=Setup.Install(options,report,cancellation.Token);});ResultCode=0;working=false;ShowPage(4);}catch(OperationCanceledException){working=false;committing=false;ShowPage(1);error.Text="已取消，原安装文件保持不变。";}catch(Exception ex){working=false;committing=false;ShowPage(uninstall?2:1);error.Text="操作未完成："+ex.Message+"。如为受限目录，请改用可写目录或以管理员身份运行。";}finally{cancellation.Dispose();cancellation=null;}}
 void Cancel(){if(working){if(!committing&&cancellation!=null){cancellation.Cancel();error.Text="正在取消…";}return;}Close();}
